curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel&limit=100" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        print(ch['id'], ch['name'])
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/users.list?token=<TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data.get('ok'):
    for u in data['members']:
        if 'leo' in u['real_name'].lower() or 'park' in u['real_name'].lower():
            print(u['id'], u['real_name'])
else:
    print('Error:', data)
"
